/* Types */
/**  One address of the open wallet. */
export type AddressRecord = {
	id: number,
	chain: ChainId,
	address: string,
	source: KeySource,
	scriptKind: ScriptKind | null,
	label: string | null,
	derivationIndex: number | null,
};

/**
 *  An asset quantity in base units. The asset supplies its decimals through
 *  `AssetId::decimals`.
 * 
 *  There's no `Add` or `Sub`, so every arithmetic method names its overflow behavior.
 */
export type Amount = string;

/**  What a typed send amount counts in. */
export type AmountEntry = 
/**  The fiat currency, converted to the asset at its current price. */
"fiat" | 
/**  The asset's own units. */
"units";

/**  The settings as the frontend sees them: whether each API key is set, never the key. */
export type AppSettings = {
	autoLockMinutes: number,
	hasEtherscanApiKey: boolean,
	hasTrongridApiKey: boolean,
	isPriceFeedEnabled: boolean,
	/**  Charts are hidden while the price feed is off, whatever this says. */
	isPriceChartEnabled: boolean,
	proxy: ProxySetting | null,
	backdrop: BackdropSetting,
	/**  At most one per chain. A chain with none shows its native coin. */
	shownTokens: TokenId[],
	fiatCurrency: FiatCurrency,
	/**  Amounts are entered in units while the price feed is off, whatever this says. */
	amountEntry: AmountEntry,
};

/**
 *  One USD price series, shared by every asset in `assets` because they trade as one
 *  ticker. Each price is US dollars per whole unit of the asset.
 */
export type AssetHistory = {
	assets: AssetId[],
	prices: DailyPrice[],
};

/**
 *  A native coin or supported token. Decimals belong to the asset, while `Amount` stores
 *  base units.
 */
export type AssetId = { kind: "native"; value: ChainId } | { kind: "token"; value: TokenId };

/**
 *  Where an asset lives and its scale. What it's called is in its coin's `CoinMeta`, and
 *  contract addresses stay in Rust on `TokenId`.
 */
export type AssetMeta = {
	asset: AssetId,
	chain: ChainId,
	coin: Coin,
	decimals: number,
};

/**
 *  One asset's total across the wallet. The interface reads its scale from the asset's
 *  metadata, as it does for a balance.
 */
export type AssetTotal = {
	asset: AssetId,
	amount: Amount,
};

/**  What the window shows behind the page, where the operating system can draw it. */
export type BackdropSetting = 
/**  A blur of whatever is behind the window, under the canvas. */
"blur" | 
/**  The opaque canvas. */
"solid";

/**
 *  An address's balance changed. The frontend refetches balances, so the event carries
 *  nothing.
 */
export type BalanceChanged = null;

/**
 *  One address's balance in one asset. The interface reads the address itself from its
 *  own record.
 * 
 *  There's no write time, because each pass restates the balance, so its age is the
 *  chain's sync state.
 */
export type BalanceRecord = {
	addressId: number,
	asset: AssetId,
	amount: Amount,
};

/**  The first, highest, lowest, and last price of one interval. */
export type Candle = {
	openUnixSecs: number,
	open: Price,
	high: Price,
	low: Price,
	close: Price,
};

/**
 *  How long one candle lasts. Kraken opens every candle at a multiple of its length
 *  since the Unix epoch, so a week opens on a Thursday.
 */
export type CandleInterval = "hour" | "day" | "week";

/**
 *  The supported chains. The database and IPC use these wire strings.
 * 
 *  The wallet lists chains as declared, so the rollups that pay fees in ether follow
 *  Ethereum.
 */
export type ChainId = "bitcoin" | "litecoin" | "dogecoin" | "bitcoin_cash" | "zcash" | "ethereum" | "arbitrum" | "base" | "optimism" | "bsc" | "polygon" | "avalanche" | "solana" | "tron" | "xrp" | "ton" | "monero";

/**
 *  The native coin's scale is in `AssetMeta` and its symbol in `CoinMeta`. The path and
 *  explorer templates use `{index}`, `{txid}`, and `{address}` placeholders.
 */
export type ChainMeta = {
	chain: ChainId,
	name: string,
	feeRateUnit: string | null,
	/**
	 *  The fee levels a send can pick from, slowest first. Empty on a chain whose
	 *  protocol fixes the fee.
	 */
	feeLevels: FeeLevel[],
	/**  What a custom fee sets, or `None` if the chain takes no custom fee. */
	customFee: CustomFee | null,
	/**  Whether a send can set its own nonce in place of the account's next one. */
	canPinNonce: boolean,
	/**  Whether a send can carry calldata in place of the generated transfer. */
	canCarryData: boolean,
	settledConfirmations: number,
	defaultPath: string,
	scriptKinds: ScriptKind[],
	defaultScript: ScriptKind | null,
	explorerTxUrl: string | null,
	explorerAddressUrl: string | null,
	canBumpFee: boolean,
	canCancel: boolean,
	/**  Whether a send can delete the sending account, as XRP's `AccountDelete` does. */
	canDeleteAccount: boolean,
	/**
	 *  Whether a payment can carry a destination tag, the number a shared receiving
	 *  account files it under.
	 */
	hasDestinationTags: boolean,
	/**
	 *  Whether a payment can carry a comment, the text a shared receiving account files
	 *  it under.
	 */
	hasComments: boolean,
	hasSubaddresses: boolean,
	canHoldStandaloneKeys: boolean,
	/**  Whether one send can spend coins from several addresses, as only a UTXO chain can. */
	canPoolSources: boolean,
};

/**
 *  A coin the wallet holds, the same on every chain that carries it: ether on Ethereum
 *  and its rollups, or USDT on every network Tether issues it on.
 */
export type Coin = "btc" | "ltc" | "doge" | "bch" | "zec" | "eth" | "bnb" | "pol" | "avax" | "sol" | "trx" | "xrp" | "gram" | "xmr" | "link" | "wbtc" | "weth" | "uni" | "shib" | "ena" | "aave" | "ondo" | "pepe" | "arb" | "op" | "pump" | "jup" | "usdt" | "usdc" | "usds" | "dai" | "usdg" | "pyusd" | "xaut" | "paxg";

/**  What the frontend shows for a coin on every chain that carries it. */
export type CoinMeta = {
	coin: Coin,
	symbol: string,
	name: string,
	isRealWorldAsset: boolean,
};

/**  An address the user saved to send to, kept with the open wallet. */
export type ContactRecord = {
	id: number,
	chain: ChainId,
	/**  Always the canonical spelling the chain's codec produced. */
	address: string,
	name: string,
	note: string | null,
};

/**
 *  A new seed wallet and the phrase generated for it.
 * 
 *  This is the only time the phrase leaves Rust without an export, because the user has to
 *  see it before the wallet is usable. Crossing IPC leaves copies we can't wipe, so the
 *  frontend must not cache this, and every later read is a password-checked export.
 */
export type CreatedWallet = {
	wallet: WalletRecord,
	phrase: string,
};

/**  What a custom fee names on a chain, and so which [`FeeSelection`] carries it. */
export type CustomFee = 
/**  A rate in the chain's fee rate unit, carried by [`FeeSelection::Rate`]. */
"rate" | 
/**  An EIP-1559 fee cap, tip, and gas limit, carried by [`FeeSelection::Evm`]. */
"fee_cap" | 
/**
 *  A gas price and gas limit, carried by [`FeeSelection::Evm`] with the cap and
 *  the tip both at the gas price, for a network whose base fee is zero.
 */
"gas_price" | 
/**  A priority fee in lamports, carried by [`FeeSelection::Solana`]. */
"priority_fee" | 
/**  The whole fee in the chain's coin, carried by [`FeeSelection::Total`]. */
"total";

export type DailyPrice = {
	/**  Unix seconds at the start of the UTC day. */
	dayUnixSecs: number,
	/**  The daily close. */
	price: Price,
};

/**
 *  The wallet database couldn't be used, so it was moved aside and this run started with
 *  an empty one.
 * 
 *  Balances and history re-sync, but wallets and their settings, chain state, addresses,
 *  contacts, endpoints, and pins exist only in the file at `moved_to`. The vault files are
 *  still there but their wallets are no longer listed, so the user has to be told.
 */
export type DatabaseRebuilt = {
	/**
	 *  The old file's path for display. It's inside the data directory, which the app
	 *  already shows.
	 */
	movedTo: string,
};

/**
 *  Unvalidated derivation-path text stored and displayed as `m/84'/0'/0'/0/0`. Parse with
 *  `jelly_keypair::parse_path` before use.
 */
export type DerivationPath = string;

/**
 *  One failed endpoint attempt. `message` is a log field that never crosses IPC, and
 *  callers must redact it before constructing this.
 */
export type EndpointAttempt = {
	/**  The endpoint's label as text, such as `https://node.example.com:8443`. */
	endpoint: string,
	kind: FailureKind,
};

/**
 *  Where a resolved endpoint came from. Declaration order is preference
 *  order among equally healthy endpoints.
 */
export type EndpointOrigin = "pinned" | "user" | "default";

/**
 *  `url` is the canonical key the other endpoint commands take, and a pinned endpoint's
 *  `origin` is `Pinned`. Health stays in Rust, and `probe_endpoint` checks an endpoint on
 *  request.
 */
export type EndpointRecord = {
	url: string,
	transport: Transport,
	origin: EndpointOrigin,
	note: string | null,
	isEnabled: boolean,
};

/**  Domain error codes. The shell adds its own codes for startup, prices, and panics. */
export type ErrorCode = "locked" | "wrong_password" | "wrong_passphrase" | "passphrase_required" | "not_found" | "already_exists" | "invalid_input" | "invalid_address" | "insufficient_funds" | "endpoints_down" | 
/**  The node returned an error response. */
"rpc" | "no_adapter" | "unsupported" | "confirmation_required" | "unknown_pending_tx" | "rebuild_required" | "rejected" | "signing" | "protocol_too_new" | "address_mismatch" | "storage" | "keychain" | "internal";

/**
 *  Network failure classes assigned by `jelly_net`. Downstream code must not reclassify
 *  error messages.
 */
export type FailureKind = "connect" | "tls" | "timeout" | "transport" | "protocol" | "rate_limited" | "server" | "client";

/**
 *  How soon a fee is priced to confirm. Every chain reads each level from its own
 *  market when the transaction is built, so a level names a speed and never a price.
 */
export type FeeLevel = "slow" | "normal" | "fast";

/**  What a transaction would pay at the selection it was quoted with. */
export type FeeQuote = {
	fee: Amount,
	/**
	 *  The quoted price as a custom fee, with every market read filled in, for a custom fee
	 *  to start from. Absent on a chain without custom fees.
	 */
	custom: FeeSelection | null,
	/**  What a send-max moves at this fee. Present only when the request is a send-max. */
	maxAmount: Amount | null,
	/**
	 *  What the same transaction would pay at each of the chain's fee levels, slowest
	 *  first. Empty on a chain whose fee is fixed, and when the market couldn't be read.
	 */
	levels: LevelFee[],
};

/**
 *  One of the chain's fee levels, or a custom fee in the chain's own unit.
 * 
 *  Every chain takes a level, and a custom fee only in the shape its spec's
 *  `custom_fee` names. Fee amounts cross IPC as strings, never floats.
 */
export type FeeSelection = 
/**
 *  Priced from the market when the transaction is built. A chain whose fee the
 *  protocol fixes pays that fee at every level.
 */
{ kind: "level"; level: FeeLevel } | 
/**  A rate in the chain's fee rate unit, as decimal text. */
{ kind: "rate"; rate: string } | 
/**
 *  An absent field takes the normal level's value, and an absent gas limit is
 *  estimated. The fields are integers, written in decimal or as `0x`-prefixed hex.
 */
{ kind: "evm"; 
/**  The most gas the transaction may use. */
gasLimit: string | null; 
/**  The most wei per gas the transaction pays, base fee and tip together. */
maxFeePerGas: string | null; 
/**  The tip in wei per gas. */
maxPriorityFeePerGas: string | null } | 
/**  The whole priority fee in lamports, spread over the measured compute units. */
{ kind: "solana"; priorityFeeLamports: string } | 
/**  The whole fee in the base units of the chain's coin. */
{ kind: "total"; fee: Amount };

/**
 *  A currency the wallet can show values in. Every one but the dollar has a Kraken pair
 *  against the dollar, and stored settings use these wire strings.
 */
export type FiatCurrency = "usd" | "eur" | "gbp" | "aud" | "cad" | "jpy" | "chf";

/**
 *  `message` is copy. It never holds a secret, a raw URL, a file path, or a library's error
 *  text. The frontend branches on `code` and `detail`, never on the wording.
 */
export type IpcError = {
	code: IpcErrorCode,
	message: string,
	detail: IpcErrorDetail | null,
};

export type IpcErrorCode = ErrorCode | ShellErrorCode;

/**
 *  Amounts stay in base units so the frontend can apply the asset's decimals.
 * 
 *  `NoAdapter` has no reason when the chain is switched off or the wallet's adapters aren't
 *  built yet.
 */
export type IpcErrorDetail = { kind: "insufficient_funds"; asset: AssetId; needed: Amount; available: Amount } | { kind: "no_adapter"; chain: ChainId; reason: SkipReason | null } | { kind: "endpoints_down"; chain: ChainId; attempts: EndpointAttempt[] } | { kind: "rejected"; rejection: RejectionKind; retry: RetryPolicy } | { kind: "protocol_too_new"; chain: ChainId; version: string } | { kind: "schema_too_new"; found: number; supported: number };

/**  Where one address's key comes from. */
export type KeySource = { kind: "derived"; path: DerivationPath } | 
/**  A standalone key held in the vault under `vault_entry`. */
{ kind: "imported"; vaultEntry: string } | 
/**
 *  A subaddress of the wallet's account on a chain whose addresses are subaddresses.
 *  One spend key covers them all.
 */
{ kind: "subaddress"; major: number; minor: number };

/**  What one fee level would pay. */
export type LevelFee = {
	level: FeeLevel,
	fee: Amount,
};

export type LockChanged = LockState;

/**  Why the wallet is locked. */
export type LockReason = 
/**  Nothing is open, or the user locked it. */
"requested" | 
/**  The session sat idle past its timeout. */
"idle";

/**
 *  The lock state the interface shows.
 * 
 *  Advisory, so anything irreversible re-reads the real state instead of trusting a
 *  stale event.
 */
export type LockState = { kind: "locked"; reason: LockReason } | { kind: "unlocked"; walletId: number; walletName: string };

/**  The passphrase a caller supplied, with the policy it implies. */
export type PassphraseInput = { kind: "none" } | { kind: "stored"; value: string } | { kind: "prompt"; value: string };

/**  Whether a wallet uses a BIP-39 passphrase and, if so, where it lives. */
export type PassphrasePolicy = "none" | 
/**  In use and kept in the vault, so unlock never asks for it. */
"stored" | 
/**  In use and never persisted, so every unlock asks for it. */
"prompt";

/**
 *  Single-use transaction authorization: 128 random bits, rendered as lowercase hex and
 *  parsed in either case.
 */
export type PendingTxId = string;

/**  How many words a generated BIP-39 phrase has. */
export type PhraseWords = "twelve" | "twenty_four";

export type Platform = "macos" | "windows" | "linux";

/**  A built and authorized transaction awaiting submit, as the interface sees it. */
export type PreparedTx = {
	id: PendingTxId,
	preview: TxPreview,
	previewDigest: PreviewDigest,
};

/**
 *  The digest a submit is bound to.
 * 
 *  The interface echoes the digest of the preview the user approved, and a submit that
 *  carries a different one is refused, so what was shown is what gets signed. It isn't a
 *  secret, so an ordinary comparison is fine.
 */
export type PreviewDigest = string;

/**
 *  The price of one unit of something in a fiat currency, in base units of
 *  `Price::DECIMALS`. The currency travels beside a price, never inside it.
 * 
 *  A price is money, so it is parsed straight into an integer and crosses IPC as
 *  a string of base units, like an `Amount`.
 */
export type Price = string;

/**  One asset's candles in one currency, oldest first. */
export type PriceChart = {
	currency: FiatCurrency,
	/**  The last is usually still open, so its close is the latest trade Kraken had. */
	candles: Candle[],
};

export type PriceHistory = {
	prices: AssetHistory[],
	rates: RateHistory[],
};

export type PriceHistoryChanged = PriceHistory;

/**
 *  What one asset was worth, and when the quote was taken.
 * 
 *  A price is shown with its age so a reader can judge it, and dropped once a day old.
 */
export type PriceRecord = {
	asset: AssetId,
	price: Price,
	asOfUnixSecs: number,
};

/**  Every price the wallet shows, all in one currency. */
export type PriceSnapshot = {
	currency: FiatCurrency,
	/**  In `AssetId` order, at most one per asset. */
	prices: PriceRecord[],
};

/**  Every price in the currency the wallet shows, sent again when the currency changes. */
export type PricesChanged = PriceSnapshot;

/**  Why a probe got no usable answer. The interface words each one itself. */
export type ProbeFailure = "timed_out" | 
/**  The connection couldn't be opened. */
"no_connection" | 
/**  The TLS handshake failed or the certificate didn't verify. */
"tls" | 
/**  The connection closed before an answer arrived. */
"dropped" | 
/**  The endpoint answered with an HTTP error status. */
"http_status" | "rate_limited" | 
/**  The endpoint answered with something this build can't use. */
"bad_answer" | 
/**  This build can't check the endpoint, so nothing was asked. */
"not_probed";

/**
 *  What one probe found.
 * 
 *  `Reachable` means there was no network to identify, as for the REST helper services.
 *  `WrongNetwork` leaves out what the host reported, a raw wire value that only the log
 *  gets.
 */
export type ProbeReport = { kind: "verified"; latencyMs: number } | { kind: "reachable"; latencyMs: number } | { kind: "wrong_network" } | { kind: "unreachable"; failure: ProbeFailure };

/**
 *  How the process reaches the network, as stored in the settings document and sent over
 *  IPC.
 */
export type ProxySetting = { kind: "system" } | { kind: "socks5h"; url: string } | { kind: "http"; url: string };

/**
 *  One exchange rate series. Each price is units of `currency` per US dollar, so a USD
 *  price times the rate is the price in `currency`.
 */
export type RateHistory = {
	currency: FiatCurrency,
	prices: DailyPrice[],
};

/**  Why the network refused a transaction. */
export type RejectionKind = "already_known" | "below_relay_fee" | "below_incremental_relay_fee" | 
/**  A required coin, output, or account is missing. */
"missing_or_spent" | "insufficient_funds" | "double_spend" | "dust" | "too_long_mempool_chain" | "nonce_too_low" | "nonce_too_high" | "replacement_underpriced" | "gas_too_low" | "stale_reference" | "reverted" | "unclassified";

/**  What the caller may do after a rejection. */
export type RetryPolicy = 
/**  The transaction is in no mempool. Rebuild and resend. */
"did_not_land" | 
/**  Every endpoint will refuse this transaction as it stands. */
"final_everywhere" | 
/**  This endpoint refused, but another may accept. */
"try_another_endpoint" | 
/**  The network already has it, so the send is done. */
"already_landed";

/**
 *  The flavors one key's address can take: a UTXO output script type, or the TON
 *  wallet contract that holds the key. The same private key produces a different
 *  address for each.
 */
export type ScriptKind = 
/**  BIP-86 taproot. */
"p2tr" | 
/**  BIP-84 native segwit. */
"p2wpkh" | 
/**  BIP-49 wrapped segwit. */
"p2sh_p2wpkh" | 
/**  BIP-44 legacy. */
"p2pkh" | "ton_v5r1" | "ton_v4r2" | "ton_v3r2";

/**  How much one outgoing transfer moves. */
export type SendAmount = { kind: "exact"; value: Amount } | 
/**  Everything the address holds of the asset, less the fee when the asset pays it. */
{ kind: "max" };

export type ShellErrorCode = 
/**  Startup timed out before the command ran. */
"starting" | 
/**  The price provider didn't answer, or prices are off. */
"prices_unavailable" | 
/**  The command task panicked. */
"panic";

/**
 *  Why a chain has no adapter after a rebuild. A builder never reports a chain the
 *  wallet switched off, since the engine already knows.
 */
export type SkipReason = 
/**
 *  The endpoint registry offered nothing to talk to, which is a configuration
 *  problem.
 */
"no_endpoints" | 
/**
 *  This wallet holds no key the chain can be scanned or spent with, and no rebuild
 *  will change that.
 */
"no_keys" | 
/**  Endpoints exist but the adapter couldn't be built. The next rebuild retries. */
"build_failed";

export type StartupChanged = StartupStatus;

/**
 *  Engine commands wait a bounded time for `Ready` or `Failed`. Both also report whether
 *  this start replaced the database, since a start can replace it and then fail.
 */
export type StartupStatus = { kind: "starting" } | { kind: "ready"; rebuilt: DatabaseRebuilt | null } | { kind: "failed"; error: IpcError; canRepairProxy: boolean; rebuilt: DatabaseRebuilt | null };

/**
 *  Supported token contracts and mints.
 * 
 *  Each chain's tokens sit together in chain order, and the wallet lists them as
 *  declared: other tokens first, then real-world assets with the dollar coins before
 *  gold, each group by market capitalization.
 */
export type TokenId = "link_erc20" | "wbtc_erc20" | "weth_erc20" | "uni_erc20" | "shib_erc20" | "ena_erc20" | "aave_erc20" | "ondo_erc20" | "pepe_erc20" | "arb_erc20" | "usdt_erc20" | "usdc_erc20" | "usds_erc20" | "dai_erc20" | "usdg_erc20" | "pyusd_erc20" | "xaut_erc20" | "paxg_erc20" | "link_arbitrum" | "weth_arbitrum" | "ena_arbitrum" | "arb_arbitrum" | "usdt_arbitrum" | "usdc_arbitrum" | "usds_arbitrum" | "usdg_arbitrum" | "pyusd_arbitrum" | "xaut_arbitrum" | "link_base" | "weth_base" | "ena_base" | "usdc_base" | "usds_base" | "link_optimism" | "weth_optimism" | "ena_optimism" | "op_optimism" | "usdt_optimism" | "usdc_optimism" | "usds_optimism" | "link_bep20" | "weth_bep20" | "ena_bep20" | "usdt_bep20" | "usdc_bep20" | "xaut_bep20" | "link_polygon" | "weth_polygon" | "usdt_polygon" | "usdc_polygon" | "pyusd_polygon" | "xaut_polygon" | "link_avalanche" | "weth_avalanche" | "usdt_avalanche" | "usdc_avalanche" | "usds_avalanche" | "xaut_avalanche" | "link_spl" | "wbtc_spl" | "ena_spl" | "pump_spl" | "jup_spl" | "usdt_spl" | "usdc_spl" | "usds_spl" | "usdg_spl" | "pyusd_spl" | "xaut_spl" | "paxg_spl" | "wbtc_trc20" | "usdt_trc20" | "ena_jetton" | "usdt_jetton" | "xaut_jetton";

/**
 *  How an endpoint is reached. The pool takes its timeout policy from it, and with the
 *  chain it picks the connector, which also checks which network the endpoint serves.
 */
export type Transport = 
/**  Electrum protocol, newline-delimited JSON-RPC over a raw TLS socket. */
"electrum_ssl" | 
/**  JSON-RPC over HTTP(S), for EVM, Solana, XRP, and TON. */
"http_jsonrpc" | 
/**
 *  JSON-RPC over a websocket, for the push subscriptions HTTP can't carry, such as
 *  EVM `eth_subscribe` and Solana `*Subscribe`.
 */
"ws_jsonrpc" | 
/**  Monero daemon RPC, a `/json_rpc` envelope plus binary sub-paths. */
"monero_rpc" | 
/**  TRON full-node HTTP API, `POST /wallet/*`. */
"tron_http" | 
/**  Transparent Zcash history, unspent outputs, and broadcast over HTTPS. */
"blockbook" | 
/**  mempool.space-family fee and mempool REST API. */
"fee_api" | 
/**  Etherscan-family transaction history REST API. */
"history_api";

/**
 *  A transaction's confirmation count changed. The frontend refetches transactions, so
 *  the event carries nothing.
 */
export type TxConfirmed = null;

/**  Decoded preview or fee detail. Labels are sentence case, not wire enum names. */
export type TxDetail = {
	label: string,
	value: string,
};

/**
 *  A transaction the wallet hadn't recorded before. The history already holds every row
 *  its sync batch wrote, so the frontend reads the wallet's view of it from there.
 */
export type TxDetected = {
	txid: TxId,
	asset: AssetId,
};

/**  How much of a transaction the sync pass saw. */
export type TxDetection = 
/**  The transaction itself was decoded. */
"full" | 
/**  Only a balance change was observed, so the details are unknown. */
"balance_delta";

/**  Which way funds moved relative to the watched address. */
export type TxDirection = "incoming" | "outgoing" | "self";

/**
 *  One transaction of one asset in the history.
 * 
 *  An outgoing amount is what reached others, without the fee. An incoming one is what
 *  reached the wallet's addresses, and a self-transfer's is what moved between them, or
 *  what came back when it all returned to one address.
 */
export type TxEntry = {
	txid: string,
	asset: AssetId,
	/**
	 *  The wallet's addresses whose own share of the transaction is outgoing or a
	 *  self-transfer.
	 */
	senderIds: number[],
	/**  The wallet's addresses whose own share of it is incoming. */
	receiverIds: number[],
	direction: TxDirection,
	outcome: TxOutcome,
	amount: Amount,
	fee: Amount | null,
	/**
	 *  What the wallet's addresses paid besides the fee to open token accounts the
	 *  transfer needed, such as the recipient's, in the native asset. `None` when they
	 *  paid none.
	 */
	rent: Amount | null,
	/**  The other side, or for a self-transfer the address it went to, when known. */
	counterparty: string | null,
	/**
	 *  The unconfirmed transaction this one pays the fee of, for a speed-up that
	 *  spends that transaction's change and moves nothing else.
	 */
	paysFor: string | null,
	height: number | null,
	/**  Unix seconds of the block, or of the first sighting while unmined. */
	timestamp: number | null,
	/**  Derived from the current tip. */
	confirmations: number,
	detection: TxDetection,
};

/**
 *  A chain-tagged transaction id. An adapter renders it canonically, but a value from IPC
 *  is unvalidated until the adapter parses it.
 */
export type TxId = {
	chain: ChainId,
	value: string,
};

/**  What the network did with a transaction. */
export type TxOutcome = "success" | 
/**  It moved nothing, but it may still have paid its fee. */
"failed" | 
/**
 *  Another transaction took its place, so it never ran, moved nothing, and paid
 *  nothing.
 */
"replaced" | "unknown";

/**  One page of history. */
export type TxPage = {
	rows: TxEntry[],
	nextCursor: string | null,
};

/**
 *  Decoded transaction for user approval. Only previewed data may be signed. The adapter
 *  supplies canonical `from` and `to` addresses.
 */
export type TxPreview = {
	chain: ChainId,
	asset: AssetId,
	/**
	 *  The sending addresses the transaction moves funds of, in the order the request
	 *  named them. Change, when there is any, returns to the first.
	 */
	from: string[],
	to: string,
	/**  The destination tag the payment carries, on a chain whose payments can carry one. */
	destinationTag: number | null,
	amount: Amount,
	fee: Amount,
	/**
	 *  What the sender pays besides the fee to open the recipient's token account, in
	 *  the native asset. Only the recipient can reclaim it.
	 */
	rent: Amount | null,
	details: TxDetail[],
	warnings: TxWarning[],
};

/**
 *  One page request against the wallet's history.
 * 
 *  A request that names an address lists that address's own share of each transaction
 *  it took part in. One that names none lists each transaction once, as the wallet's
 *  addresses together saw it.
 */
export type TxQuery = {
	/**  `None` lists every chain the wallet has switched on. */
	chain: ChainId | null,
	asset: AssetId | null,
	addressId: number | null,
	txid: string | null,
	direction: TxDirection | null,
	cursor: string | null,
	/**  Zero means the shipped page size. */
	limit: number,
};

/**  The user's intent for one outgoing transfer. */
export type TxRequest = {
	/**
	 *  The addresses the transfer spends from, in the order the user chose them. A UTXO
	 *  chain pools their coins and returns change to the first. Every other chain takes
	 *  exactly one.
	 */
	fromAddressIds: number[],
	/**  As the user typed it. The adapter validates it against the chain. */
	to: string,
	/**  The XRP destination tag. Every other chain refuses a request that carries one. */
	destinationTag: number | null,
	comment: string | null,
	/**
	 *  Deletes the sending account and pays the recipient everything it holds, less the
	 *  deletion fee. Only a chain whose spec allows it takes one, and the amount must be
	 *  [`SendAmount::Max`].
	 */
	shouldDeleteAccount: boolean,
	asset: AssetId,
	amount: SendAmount,
	fee: FeeSelection,
	/**
	 *  Used instead of the sending account's next nonce. Only a chain whose spec allows it
	 *  takes one.
	 */
	nonce: number | null,
	/**
	 *  Calldata as hex, with or without `0x`, sent in place of the generated transfer.
	 *  Only a chain whose spec allows it takes any.
	 */
	data: string | null,
};

/**
 *  A transaction the wallet already recorded changed. The frontend refetches transactions,
 *  so the event carries nothing.
 */
export type TxUpdated = null;

/**
 *  A warning shown before signing. `message` is displayed verbatim and must use complete,
 *  sentence-case sentences ending in periods.
 */
export type TxWarning = {
	kind: TxWarningKind,
	message: string,
};

/**  Why a preview carries a warning. */
export type TxWarningKind = "dust_output" | 
/**
 *  The fee is unusually high: far above the market's rate, or above the chain's
 *  high-fee limit.
 */
"high_fee" | "dropped_change" | "ambiguous_address" | "remote_decoys" | "account_activation" | "account_deletion" | "rent_exemption" | "replacement" | 
/**  A second transaction that pays the fee of an unconfirmed one. */
"child_pays" | "estimated" | "other";

/**
 *  Opaque sRGB stored as lowercase `#rrggbb`. Display balancing doesn't change the saved
 *  color.
 */
export type WalletColor = string;

/**  One wallet as the interface sees it. */
export type WalletRecord = {
	id: number,
	name: string,
	color: WalletColor,
	createdAtUnixSecs: number,
	passphrasePolicy: PassphrasePolicy,
	restoreHeights: Partial<{ [key in ChainId]: number }>,
	enabledChains: ChainId[],
};

/**  What fills the window behind the page. */
export type WindowBackdrop = 
/**
 *  The window is transparent over a layer the app draws, either a tinted blur of
 *  what's behind the window or the plain canvas. The page leaves its canvas
 *  unpainted.
 */
"composed" | 
/**  The window paints the canvas, and so does the page. */
"solid";

/**  Who draws the buttons that minimize, maximize, and close the window. */
export type WindowControls = 
/**  The page draws them at the right end of its title bar. */
"page" | 
/**  The system draws them over the page's title bar. */
"system";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

